-- Los 30 libros del catálogo, los mismos de data/libros.json, con sus id: así las direcciones
-- /libros/{id} del TP4 siguen llevando al mismo libro.
--
-- Va después de esquema.sql y también se puede volver a correr: un libro que ya está no se pisa
-- (ON DUPLICATE KEY no cambia nada), así lo que se haya editado desde el sitio se conserva.
--
--   mysql -u root -p < pawprints/backend/db/libros.sql

-- El archivo está en UTF-8. Sin esto, un cliente mysql que arranca en latin1 (pasa en algunas
-- instalaciones y contenedores) guarda «Ficción» como «FicciÃ³n».
SET NAMES utf8mb4;

USE pawprints;

ON DUPLICATE KEY UPDATE id = libros.id;
