INSERT INTO libros (id, titulo, autor, genero, isbn, formato, precio, stock, resumen, descripcion, imagen) VALUES
    (1, 'El Laberinto de los Vientos', 'Salvador Baez', 'Ficción', '978-987-1234-56-1', 'Tapa Dura', 16500, 7, 'Una misteriosa travesía a través de ciudades olvidadas donde las ráfagas del viento custodian antiguos secretos.', 'Una misteriosa travesía a través de ciudades olvidadas donde las ráfagas del viento custodian antiguos secretos. En esta apasionante obra de ficción, Salvador Baez explora los límites de la memoria, el destino y los lazos invisibles que unen a las personas en momentos de encrucijada.', 'libro-1.jpg'),
    (2, 'El Secreto de la Torre', 'Tomás Resnik', 'Ficción', '978-987-1400-72-0', 'Tapa Blanda', 14000, 4, 'Una intriga detectivesca en una fortaleza medieval donde cada manuscrito encierra un dilema peligroso.', 'Una intriga detectivesca en una fortaleza medieval donde cada manuscrito encierra un dilema peligroso. Resnik construye una novela de encierro y sospecha en la que la biblioteca de la torre funciona como un personaje más: cada libro que se abre cambia lo que los demás significan.', 'libro-2.jpg'),
    (3, 'Sombras en el Horizonte', 'Mateo Nomico', 'Ficción', '978-987-2155-83-4', 'Epub / Digital', 15800, 12, 'Una novela profunda sobre viajes marítimos, horizontes lejanos y la búsqueda constante de libertad.', 'Una novela profunda sobre viajes marítimos, horizontes lejanos y la búsqueda constante de libertad. A lo largo de tres travesías que ocurren en siglos distintos, Nomico narra la misma pregunta repetida: qué queda de una persona cuando pierde de vista la costa.', 'libro-3.jpg'),
    (4, 'Ecos del Cosmos', 'Salvador Baez', 'Ciencia', '978-987-3044-19-9', 'Tapa Dura', 17200, 5, 'Un recorrido fascinante por los misterios del universo, ondas de radio interestelares y física teórica.', 'Un recorrido fascinante por los misterios del universo, ondas de radio interestelares y física teórica. El libro parte de una pregunta sencilla —qué escuchamos cuando apuntamos una antena al cielo— y la sigue hasta los límites de lo que la física actual puede responder, sin pedirle al lector más que curiosidad.', 'libro-4.jpg'),
    (5, 'Crónicas del Tiempo Olvidado', 'Tomás Resnik', 'Historia', '978-987-4122-04-9', 'Tapa Dura', 18500, 3, 'Un compendio de pasajes históricos poco conocidos que transformaron el rumbo de antiguas civilizaciones.', 'Un compendio de pasajes históricos poco conocidos que transformaron el rumbo de antiguas civilizaciones. Cada capítulo reconstruye un episodio menor —una sequía, un malentendido diplomático, un cargamento perdido— y muestra cómo decidió el destino de imperios enteros.', 'libro-5.jpg'),
    (6, 'La Arquitectura de la Mente', 'Mateo Nomico', 'Arte & Diseño', '978-987-5988-31-6', 'Tapa Blanda', 13900, 9, 'Un ensayo visual y conceptual sobre cómo la percepción del espacio moldea las ideas creativas.', 'Un ensayo visual y conceptual sobre cómo la percepción del espacio moldea las ideas creativas. Entre planos, fotografías y apuntes de taller, Nomico sostiene que no pensamos a pesar del lugar donde estamos, sino con él.', 'libro-6.jpg'),
    (7, 'Ángeles de Papel', 'Lucía Ferraro', 'Ficción', '978-987-6959-49-7', 'Tapa Blanda', 9800, 11, 'Una costurera de Mercedes descubre que las cartas que remienda cambian el destino de quienes las escribieron.', 'Una costurera de Mercedes descubre que las cartas que remienda cambian el destino de quienes las escribieron. Ambientada en un taller de barrio, la novela sigue a una costurera que repara cartas viejas y, sin querer, reescribe las vidas de sus autores. Ferraro mezcla lo cotidiano con lo fantástico en una prosa tierna y precisa.', 'libro-1.jpg'),
    (8, 'Breve Historia del Río', 'Joaquín Méndez', 'Historia', '978-987-7096-56-8', 'Tapa Dura', 24500, 3, 'Cuatro siglos de historia contados desde las orillas del río Luján y la gente que vivió de él.', 'Cuatro siglos de historia contados desde las orillas del río Luján y la gente que vivió de él. Méndez recorre la historia de la región siguiendo el curso del río: los primeros asentamientos, las inundaciones, los molinos y los puentes. Un libro de divulgación con mapas y testimonios recuperados de archivos locales.', 'libro-5.jpg'),
    (9, 'Cartografía del Silencio', 'Valentina Ríos', 'Arte & Diseño', '978-987-7233-63-9', 'Tapa Dura', 32000, 6, 'Un ensayo visual sobre el espacio vacío en la arquitectura, la tipografía y la pintura.', 'Un ensayo visual sobre el espacio vacío en la arquitectura, la tipografía y la pintura. Ríos propone mirar lo que no está: los márgenes de una página, el patio de una casa, el blanco de un cuadro. Con más de cien ilustraciones, el libro enseña a leer el silencio como parte del diseño.', 'libro-6.jpg'),
    (10, 'Diario de una Estrella Fugaz', 'Martín Quiroga', 'Ciencia', '978-987-7370-70-0', 'Epub / Digital', 8000, 9, 'La vida breve y luminosa de un meteoro, contada con humor y rigor para lectores curiosos.', 'La vida breve y luminosa de un meteoro, contada con humor y rigor para lectores curiosos. Quiroga narra en primera persona el viaje de un meteoro desde el cinturón de asteroides hasta la atmósfera terrestre. Entre anécdota y anécdota, explica la física del espacio de manera accesible y divertida.', 'libro-4.jpg'),
    (11, 'El Último Faro', 'Lucía Ferraro', 'Ficción', '978-987-7507-77-1', 'Tapa Dura', 18900, 1, 'En una isla del sur, el último farero se niega a abandonar su puesto cuando llega la automatización.', 'En una isla del sur, el último farero se niega a abandonar su puesto cuando llega la automatización. Una novela sobre la obstinación y el oficio. Ferraro construye un personaje inolvidable que, solo frente al mar, se pregunta qué vale un trabajo cuando ya nadie lo necesita.', 'libro-2.jpg'),
    (12, 'Ética para Máquinas', 'Andrés Salvatierra', 'Ciencia', '978-987-7644-84-2', 'Tapa Blanda', 21000, 4, '¿Puede una máquina distinguir el bien del mal? Un recorrido por los dilemas de la inteligencia artificial.', '¿Puede una máquina distinguir el bien del mal? Un recorrido por los dilemas de la inteligencia artificial. Salvatierra repasa los grandes debates de la filosofía moral y los pone a prueba frente a los algoritmos que hoy toman decisiones por nosotros. Un libro claro y provocador, sin tecnicismos innecesarios.', 'libro-4.jpg'),
    (13, 'Flores de Invierno', 'Camila Duarte', 'Ficción', '978-987-7781-91-3', 'Epub / Digital', 11500, 7, 'Tres generaciones de mujeres comparten una casa, un jardín y un secreto que nadie se anima a nombrar.', 'Tres generaciones de mujeres comparten una casa, un jardín y un secreto que nadie se anima a nombrar. Duarte entreteje las voces de una abuela, su hija y su nieta durante un invierno largo. Una novela coral sobre la memoria familiar y las cosas que florecen cuando nadie las espera.', 'libro-3.jpg'),
    (14, 'Geometría de las Ciudades', 'Valentina Ríos', 'Arte & Diseño', '978-987-7918-98-4', 'Tapa Blanda', 19500, 10, 'Cómo las formas simples —el círculo, la grilla, la diagonal— dieron forma a las ciudades que habitamos.', 'Cómo las formas simples —el círculo, la grilla, la diagonal— dieron forma a las ciudades que habitamos. Desde las plazas fundacionales hasta los barrios jardín, Ríos analiza el trazado urbano como un problema de diseño. Planos, fotografías y dibujos propios acompañan cada capítulo.', 'libro-6.jpg'),
    (15, 'Historias de la Pampa', 'Joaquín Méndez', 'Historia', '978-987-8055-05-5', 'Tapa Blanda', 15000, 2, 'Relatos documentados de estancias, pulperías y caminos de la llanura bonaerense en el siglo XIX.', 'Relatos documentados de estancias, pulperías y caminos de la llanura bonaerense en el siglo XIX. Méndez reúne quince historias reales rescatadas de diarios, cartas y expedientes judiciales. Juntas, arman un retrato vivo de la vida cotidiana en la pampa antes del ferrocarril.', 'libro-5.jpg'),
    (16, 'Ingeniería del Asombro', 'Martín Quiroga', 'Ciencia', '978-987-8192-12-6', 'Tapa Dura', 27500, 5, 'Los inventos más extraños de la historia y la ciencia que los hizo posibles (o imposibles).', 'Los inventos más extraños de la historia y la ciencia que los hizo posibles (o imposibles). De las máquinas voladoras de madera a los relojes que funcionan con la presión del aire, Quiroga explica qué tenían de genial y qué de disparatado los inventos que cambiaron —o casi— el mundo.', 'libro-4.jpg'),
    (17, 'La Biblioteca Infinita', 'Camila Duarte', 'Ficción', '978-987-8329-19-7', 'Tapa Dura', 22800, 8, 'Una bibliotecaria encuentra un libro que se reescribe cada vez que alguien lo lee.', 'Una bibliotecaria encuentra un libro que se reescribe cada vez que alguien lo lee. Entre el policial y lo fantástico, Duarte imagina una biblioteca de pueblo donde un solo libro guarda todas las historias posibles. Un homenaje a los lectores y a los lugares donde los libros esperan.', 'libro-1.jpg'),
    (18, 'Manual del Color', 'Valentina Ríos', 'Arte & Diseño', '978-987-8466-26-8', 'Epub / Digital', 12000, 11, 'Una guía práctica para elegir, combinar y usar el color en ilustración, diseño gráfico y espacios.', 'Una guía práctica para elegir, combinar y usar el color en ilustración, diseño gráfico y espacios. Ríos explica la teoría del color con ejercicios simples y ejemplos de obras conocidas. Ideal para estudiantes y para cualquiera que alguna vez dudó entre dos tonos de pintura.', 'libro-6.jpg'),
    (19, 'Mareas Interiores', 'Lucía Ferraro', 'Ficción', '978-987-8603-33-9', 'Tapa Blanda', 14000, 3, 'Un verano en la costa atlántica obliga a dos hermanos distanciados a reconstruir lo que perdieron.', 'Un verano en la costa atlántica obliga a dos hermanos distanciados a reconstruir lo que perdieron. Ferraro narra con delicadeza el reencuentro de dos hermanos en la casa de veraneo de su infancia. Una novela breve sobre el perdón, el paso del tiempo y las mareas que vuelven siempre.', 'libro-2.jpg'),
    (20, 'Microbios Amigos', 'Andrés Salvatierra', 'Ciencia', '978-987-8740-40-0', 'Tapa Blanda', 13500, 6, 'Las bacterias que nos habitan, nos protegen y nos ayudan a vivir, explicadas sin miedo.', 'Las bacterias que nos habitan, nos protegen y nos ayudan a vivir, explicadas sin miedo. Salvatierra derriba mitos sobre los microorganismos y cuenta cómo la ciencia descubrió que somos, en buena medida, un ecosistema. Con ilustraciones y experimentos para hacer en casa.', 'libro-4.jpg'),
    (21, 'Noches de Tango', 'Tomás Resnik', 'Historia', '978-987-8877-47-1', 'Epub / Digital', 10500, 9, 'Los cafés, las orquestas y los poetas que hicieron del tango la música de una ciudad.', 'Los cafés, las orquestas y los poetas que hicieron del tango la música de una ciudad. Resnik reconstruye la historia del tango desde los conventillos hasta los grandes salones, a través de las vidas de músicos, bailarines y letristas. Incluye una discografía comentada.', 'libro-5.jpg'),
    (22, 'Órbitas Cruzadas', 'Martín Quiroga', 'Ciencia', '978-987-9014-54-2', 'Epub / Digital', 16500, 1, 'Una introducción amena a la mecánica celeste: por qué los planetas giran como giran.', 'Una introducción amena a la mecánica celeste: por qué los planetas giran como giran. Con ejemplos cotidianos y gráficos claros, Quiroga explica las leyes que gobiernan el movimiento de planetas, lunas y satélites. Un libro para mirar el cielo de otra manera.', 'libro-4.jpg'),
    (23, 'Puentes de Hierro', 'Joaquín Méndez', 'Historia', '978-987-9151-61-3', 'Tapa Dura', 29900, 4, 'La llegada del ferrocarril y cómo transformó los pueblos de la provincia de Buenos Aires.', 'La llegada del ferrocarril y cómo transformó los pueblos de la provincia de Buenos Aires. Méndez investiga la construcción de las líneas férreas, las estaciones y los puentes que unieron la provincia. Un estudio documentado con planos originales y fotografías de época.', 'libro-5.jpg'),
    (24, 'Retratos sin Rostro', 'Valentina Ríos', 'Arte & Diseño', '978-987-9288-68-4', 'Tapa Dura', 35000, 7, 'Una colección de retratos contemporáneos que prescinden de la cara para contar quién es alguien.', 'Una colección de retratos contemporáneos que prescinden de la cara para contar quién es alguien. Manos, objetos, espaldas y habitaciones: Ríos reúne el trabajo de veinte artistas que retratan a las personas por lo que las rodea. Una edición de lujo, impresa a todo color.', 'libro-6.jpg'),
    (25, 'Susurros del Bosque', 'Camila Duarte', 'Ficción', '978-987-9425-75-5', 'Tapa Blanda', 12900, 10, 'Una niña se pierde en el bosque y vuelve con historias que nadie en el pueblo quiere escuchar.', 'Una niña se pierde en el bosque y vuelve con historias que nadie en el pueblo quiere escuchar. Una novela de iniciación con aires de cuento popular. Duarte juega con los mitos del monte y con la pregunta de qué es real cuando los adultos dejan de creer.', 'libro-3.jpg'),
    (26, 'Teoría del Caos Cotidiano', 'Andrés Salvatierra', 'Ciencia', '978-987-9562-82-6', 'Tapa Dura', 23500, 2, 'Por qué el clima, el tránsito y las colas del supermercado son tan difíciles de predecir.', 'Por qué el clima, el tránsito y las colas del supermercado son tan difíciles de predecir. Salvatierra presenta los sistemas complejos con ejemplos de todos los días y sin una sola ecuación difícil. Un libro que cambia la forma de entender el azar y el orden.', 'libro-4.jpg'),
    (27, 'Una Casa en Mercedes', 'Tomás Resnik', 'Historia', '978-987-9699-89-7', 'Tapa Blanda', 17000, 5, 'La historia de una casona de la ciudad y de las familias que la habitaron durante ciento cincuenta años.', 'La historia de una casona de la ciudad y de las familias que la habitaron durante ciento cincuenta años. Resnik sigue la vida de una casa desde su construcción hasta hoy, y a través de ella cuenta la historia de la ciudad. Con fotografías del archivo municipal y testimonios de vecinos.', 'libro-5.jpg'),
    (28, 'Viaje al Centro del Papel', 'Mateo Nomico', 'Arte & Diseño', '978-987-9836-96-8', 'Tapa Blanda', 9500, 8, 'Todo lo que hay que saber sobre el papel: su historia, sus tipos y cómo elegirlo para cada proyecto.', 'Todo lo que hay que saber sobre el papel: su historia, sus tipos y cómo elegirlo para cada proyecto. Nomico recorre la historia del papel desde los primeros pliegos hasta los papeles de diseño actuales. Una guía práctica para ilustradores, encuadernadores y amantes de los libros.', 'libro-6.jpg'),
    (29, 'Yo, el Inventario', 'Mateo Nomico', 'Ficción', '978-987-9973-03-9', 'Epub / Digital', 8900, 11, 'El inventario de una librería cobra vida y decide contar su propia versión de los hechos.', 'El inventario de una librería cobra vida y decide contar su propia versión de los hechos. Una novela breve y desopilante narrada por la planilla de stock de una librería. Nomico se ríe del oficio librero y, de paso, le rinde homenaje.', 'libro-1.jpg'),
    (30, 'Zafiros del Desierto', 'Salvador Baez', 'Ficción', '978-987-1011-10-0', 'Tapa Dura', 26000, 3, 'Una expedición en busca de una mina legendaria en la Puna termina convertida en una lucha por sobrevivir.', 'Una expedición en busca de una mina legendaria en la Puna termina convertida en una lucha por sobrevivir. Baez vuelve a la aventura con una novela de ritmo vertiginoso, paisajes extremos y personajes al límite. Una historia sobre la codicia, la amistad y lo que el desierto guarda.', 'libro-2.jpg')
